package blob

import (
	"strings"
	"testing"
)

// TestDetectGenerated_Sourcemap 은 Issue-3144 의 핵심 케이스 — 인라인 sourcemap
// data URI 감지. enry 는 이 시그니처를 안 잡으므로 우리 tail-scan 이 단독으로
// 잡아내야 한다.
func TestDetectGenerated_Sourcemap(t *testing.T) {
	tests := []struct {
		name    string
		path    string
		content string
		want    GeneratedKind
	}{
		{
			name:    "inline sourcemap data URI (//#) — modern",
			path:    "src/main.tsx",
			content: "export const x = 1;\n//# sourceMappingURL=data:application/json;base64,eyJ2IjozfQ==",
			want:    GeneratedSourcemapDataURI,
		},
		{
			name:    "inline sourcemap data URI (//@) — legacy",
			path:    "src/main.js",
			content: "var x=1;\n//@ sourceMappingURL=data:application/json;base64,e30=",
			want:    GeneratedSourcemapDataURI,
		},
		{
			name:    "inline sourcemap data URI in CSS (/*#)",
			path:    "src/style.css",
			content: ".a{color:red}\n/*# sourceMappingURL=data:application/json;base64,e30= */",
			want:    GeneratedSourcemapDataURI,
		},
		{
			name:    "external sourcemap reference (not data URI) — should NOT match sourcemap kind",
			path:    "src/foo.tsx",
			content: "export const x = 1;\n//# sourceMappingURL=foo.tsx.map",
			want:    GeneratedNone,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := DetectGenerated(tt.path, []byte(tt.content))
			if got != tt.want {
				t.Errorf("DetectGenerated(%q) = %q, want %q", tt.path, got, tt.want)
			}
		})
	}
}

// TestDetectGenerated_DelegatesToLinguist 는 enry 가 신뢰성 있게 잡아주는
// 케이스들이 GeneratedLinguist 또는 GeneratedVendored 로 분류되는지 확인.
//
// 일부 케이스 (yarn.lock 빈 콘텐츠, *.bundle.js 등) 는 linguist 가 content
// 시그니처를 함께 보거나 그 패턴을 다루지 않기 때문에 분류되지 않을 수 있다 —
// 그건 GitHub 도 마찬가지이므로 우리도 동일한 동작을 받아들인다. 여기서는
// "enry 위임이 실제로 작동한다" 만 회귀시키면 충분.
func TestDetectGenerated_DelegatesToLinguist(t *testing.T) {
	tests := []struct {
		name    string
		path    string
		content string
	}{
		{name: "package-lock.json", path: "package-lock.json", content: "{}"},
		{name: "Cargo.lock", path: "Cargo.lock", content: "[[package]]\nname=\"x\"\n"},
		{name: "vendored node_modules", path: "node_modules/react/index.js", content: "module.exports={}"},
		{name: "vendored vendor", path: "vendor/lib/x.go", content: "package lib"},
		{name: "minified js", path: "vendor.min.js", content: "var x=1;"},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got := DetectGenerated(tt.path, []byte(tt.content))
			if got == GeneratedNone {
				t.Errorf("expected non-None for %q, got %q", tt.path, got)
			}
			if got == GeneratedSourcemapDataURI {
				t.Errorf("path %q should not match sourcemap kind, got %q", tt.path, got)
			}
		})
	}
}

// TestDetectGenerated_NormalSource 는 정상 source 가 GeneratedNone 인지
// 확인 — false positive 회귀 방지.
func TestDetectGenerated_NormalSource(t *testing.T) {
	tests := []struct {
		path    string
		content string
	}{
		{path: "src/App.tsx", content: "export const App = () => <div/>;"},
		{path: "internal/foo/bar.go", content: "package foo"},
		{path: "README.md", content: "# Hi"},
		{path: "cmd/server/main.go", content: "package main"},
	}
	for _, tt := range tests {
		t.Run(tt.path, func(t *testing.T) {
			got := DetectGenerated(tt.path, []byte(tt.content))
			if got != GeneratedNone {
				t.Errorf("DetectGenerated(%q) = %q, want GeneratedNone (false positive on normal source)", tt.path, got)
			}
		})
	}
}

// TestDetectGenerated_SourcemapAtEndOfLargeFile 는 sourcemap data URI 가
// 매우 큰 파일의 끝쪽에 있어도 감지된다는 것을 확인 (sourcemap 코멘트는
// 파일 말미 관습).
func TestDetectGenerated_SourcemapAtEndOfLargeFile(t *testing.T) {
	body := strings.Repeat("export const x = 1;\n", 5000) // ~100KB
	body += "//# sourceMappingURL=data:application/json;base64,eyJ2IjozfQ=="

	got := DetectGenerated("src/main.tsx", []byte(body))
	if got != GeneratedSourcemapDataURI {
		t.Errorf("DetectGenerated should detect sourcemap at end of large file, got %q", got)
	}
}

// TestDetectGenerated_SourcemapBeyondScanWindow 는 sourcemap 마커가 파일
// 시작 부근에만 있고 끝 64KB 윈도우 바깥이라면 매칭되지 않는다는 것을 확인 —
// false positive 방지 (정상 source 가 코멘트로 sourcemap 키워드를 적은 케이스).
func TestDetectGenerated_SourcemapBeyondScanWindow(t *testing.T) {
	prefix := "// historical note: //# sourceMappingURL=data:foo\n"
	body := prefix + strings.Repeat("export const x = 1;\n", 6000) // ~120KB 뒤꼬리

	got := DetectGenerated("src/main.tsx", []byte(body))
	if got == GeneratedSourcemapDataURI {
		t.Errorf("sourcemap marker outside end-scan window should not match sourcemap kind, got %q", got)
	}
}

func TestGeneratedKind_HumanReason(t *testing.T) {
	cases := map[GeneratedKind]string{
		GeneratedNone:             "",
		GeneratedSourcemapDataURI: "File contains an inline source map (generated by a bundler)",
		GeneratedLinguist:         "File is generated (minified, codegen output, or lockfile)",
		GeneratedVendored:         "File is in a vendored or build-output directory",
	}
	for kind, want := range cases {
		if got := kind.HumanReason(); got != want {
			t.Errorf("HumanReason(%q) = %q, want %q", kind, got, want)
		}
	}
}
